// Тикет #6a86f7fd · 6a86f7fd7a0ea006134e7fe1 F-36 «פיתוח: תלות חיצונית במסירת תזכורות והתראות» — принят 13.10.2026 (iPhone, TestFlight 1.0.0 (19)).
// Кейс .qa/tests/reminders/RM-09-prayer-push-delivery.md. Факты 13.10:
//   שחרית на 14:59 → в 14:59 push «שחרית / תזכורת יומית בשעה 14:59» (центр уведомлений iOS: «אור הגאולה, …, שחרית, תזכורת יומית בשעה 14:59»), приложение свёрнуто;
//   מנחה поставлена на 14:40 в 15:01 (прошедшее) — push не пришёл (AC4); уведомления запрещены → ערבית 15:22 не пришёл (AC5).
// @manual-check: каждый тест ждёт push 2–4 минуты — запуск только с QA_PUSH=1. Время ставится на экране «תפילות»,
//   который в сборке 19 падает (#70e8283a) → тогда skip с причиной; время можно выставить в web expo.app/prayers (COVERAGE-1310.md).
// «Не больше одного push в день на молитву» — только вручную (RM-09 п.5).
// @data: время и switch молитвы возвращаются к исходным в finally.
import { expect } from '@wdio/globals';
import { toHome } from '../../helpers/app.ts';
import { skipWith } from '../_lib/app-0710.ts';
import {
  backgroundApp, deviceClock, shiftClock, hhmm, openPrayersReminders, openPrayerReminderEditor, setPrayerReminder,
  waitPrayerNotification, returnToApp, openProfileReminders, sysRemindersOn, toggleSysReminders,
  PRAYERS_CRASH, type PrayerName, type PrayerReminderState,
} from '../_lib/app-1310b.ts';

const NEED_PUSH = 'push-тест ждёт 2–4 мин — запускать с QA_PUSH=1 (телефон не блокировать, «Не беспокоить» выкл)';

/** Вернуть время/switch молитвы. Пустое исходное время — только выключить switch. */
async function restorePrayer(p: PrayerName, orig: PrayerReminderState | null) {
  if (!orig) return;
  await returnToApp().catch(() => {});
  if (!(await openPrayersReminders(p))) return;
  await openPrayerReminderEditor(p);
  if (orig.hours && orig.minutes) await setPrayerReminder(p, orig.hours, orig.minutes, orig.on);
  else if (!orig.on) await setPrayerReminder(p, '00', '00', false).catch(() => {});
}

/** Включить «תזכורות במערכת», если выключен. Возвращает исходное состояние. */
async function ensureSysRemindersOn(): Promise<boolean> {
  await openProfileReminders();
  const was = await sysRemindersOn();
  if (!was) await toggleSysReminders();
  return was;
}
async function restoreSysReminders(was: boolean) {
  await openProfileReminders();
  if ((await sysRemindersOn()) !== was) await toggleSysReminders();
}

describe('Напоминания — push по молитвам (F-36)', () => {
  afterEach(async () => { await toHome().catch(() => {}); });

  it('RM-09a Своё время שחרית (+2 мин) → push «שחרית / תזכורת יומית בשעה HH:MM» при свёрнутом приложении #6a86f7fd @data @manual-check', async function () {
    if (process.env.QA_PUSH !== '1') skipWith(this, NEED_PUSH);
    const sysWas = await ensureSysRemindersOn();
    let orig: PrayerReminderState | null = null;
    try {
      if (!(await openPrayersReminders('שחרית'))) skipWith(this, PRAYERS_CRASH);
      orig = await openPrayerReminderEditor('שחרית');
      const at = shiftClock(await deviceClock(), 2);
      await setPrayerReminder('שחרית', at.h, at.m, true);   // → «התזכורת פעילה ומוצגת במסך הבית.»
      await backgroundApp();
      const hit = await waitPrayerNotification('שחרית', hhmm(at), 4 * 60_000);
      expect(hit).not.toBeNull();
      expect(hit!).toContain(`תזכורת יומית בשעה ${hhmm(at)}`);
    } finally {
      await restorePrayer('שחרית', orig);
      await restoreSysReminders(sysWas);
    }
  });

  it('RM-09b AC4 Время уже прошло (−20 мин) → push сегодня не приходит #6a86f7fd @data @manual-check', async function () {
    if (process.env.QA_PUSH !== '1') skipWith(this, NEED_PUSH);
    const sysWas = await ensureSysRemindersOn();
    let orig: PrayerReminderState | null = null;
    try {
      if (!(await openPrayersReminders('מנחה'))) skipWith(this, PRAYERS_CRASH);
      orig = await openPrayerReminderEditor('מנחה');
      const at = shiftClock(await deviceClock(), -20);
      await setPrayerReminder('מנחה', at.h, at.m, true);
      await backgroundApp();
      expect(await waitPrayerNotification('מנחה', hhmm(at), 2 * 60_000)).toBeNull();
    } finally {
      await restorePrayer('מנחה', orig);
      await restoreSysReminders(sysWas);
    }
  });

  it('RM-09c AC5 Уведомления запрещены в ОС → push ערבית (+2 мин) не приходит #6a86f7fd @data @manual-check', async function () {
    if (process.env.QA_PUSH !== '1') skipWith(this, NEED_PUSH);
    if (process.env.QA_NOTIF_DENIED !== '1') skipWith(this, 'запретить уведомления «אור הגאולה» в настройках ОС и задать QA_NOTIF_DENIED=1');
    let orig: PrayerReminderState | null = null;
    try {
      if (!(await openPrayersReminders('ערבית'))) skipWith(this, PRAYERS_CRASH);
      orig = await openPrayerReminderEditor('ערבית');
      const at = shiftClock(await deviceClock(), 2);
      await setPrayerReminder('ערבית', at.h, at.m, true);
      await backgroundApp();
      expect(await waitPrayerNotification('ערבית', hhmm(at), 4 * 60_000)).toBeNull();
    } finally {
      await restorePrayer('ערבית', orig);
    }
  });
});
